dataComparisonFormat:
{
"key field":"Variant ID",
"fields group data key":["phenotype"],
"fields to compare":["-log10(P-Value)","P-Value","Beta","MAF","Standard Error","Z Score"]
}

filters:
[
{
                "field": "Variant ID",
                "label": "Variant ID",
                "type": "search",
"label in bubble":"true"
            },
{
                "field": "P-Value",
                "label": "P-Value (<=)",
                "type": "search lower than",
"label in bubble":"true"
            },
{
                "field": "EAF",
                "label": "EAF (>=)",
                "type": "search greater than",
"label in bubble":"true"
            },
{
                "field": "Beta",
                "label": "Beta (>=)",
                "type": "search greater than",
"label in bubble":"true"
            },
{
                "field": "Z Score",
                "label": "Z Score (>=)",
                "type": "search greater than",
"label in bubble":"true"
            }
]

visualizerConfiguration:
{"type":"gem package",
"viewers": ["region plot", "genes plot", "credible sets plot","annotations plot"],
"pkg id": "testPkg",
"region viewer": {
  "x axis field": "Position",
  "y axis field": "-log10(P-Value)",
  "render by": "Variant ID",
  "y axis label": "-Log10(p-value)",
  "x axis label": "Chromosome",
  "hover content": ["P-Value", "Beta"],
  "height": 120,
  "ld server": {"pos": "Position","ref": "ref","alt": "alt","ref variant field": "Variant ID","populations field": "P-Value","populations type": "fixed","fixed population": "ALL","populations": { "ALL": "ALL" }}
  },
"credible sets viewer":{
  "credible sets server":"KP BioIndex",
  "phenotype parameter":"phenotype",
  "x axis field": "position",
  "y axis field": "posteriorProbability",
  "hover content":["posteriorProbability","credibleSetId"],
  "render by":"Variant ID",
  "data convert":[
    {"type":"join multi","field name":"Variant ID","fields to join":["chromosome","position","reference","alt"],"join by":[":","_","/"]}
  ],
"phenotype match":{
"BMI":"BMI","T2D":"T2D"
}
},
"annotations viewer":{
  "annotations server":"KP BioIndex",
  "phenotype parameter":"phenotype"
},
"genes track": {"input type": "dynamic","dynamic parameter": "region"},
"zoom":"true"
}
